recipes.code:
{
  "inputs": [
    {
      "id": "vips-api-key",
      "type": "promptString",
      "description": "VIPsAllowed API key (vips_...). Optional: without a key the CLI can self-signup via 'vips signup'.",
      "password": true
    }
  ],
  "servers": {
    "vips": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "mcp-serve",
        "vipsallowed@1.2.1"
      ],
      "env": {
        "VIPS_API_KEY": "${input:vips-api-key}",
        "VIPS_URL": "<vips-url>"
      }
    }
  }
}
